// Copyright (c) 2026 Roshan. All rights reserved.package com.roshan.persona.permissionsimport android.content.Contextimport android.content.pm.PackageManagerimport android.os.Buildimport androidx.activity.compose.rememberLauncherForActivityResultimport androidx.activity.result.contract.ActivityResultContractsimport androidx.compose.runtime.Composableimport androidx.compose.runtime.LaunchedEffectimport androidx.compose.runtime.Stableimport androidx.compose.runtime.getValueimport androidx.compose.runtime.mutableStateOfimport androidx.compose.runtime.rememberimport androidx.compose.runtime.setValueimport androidx.core.content.ContextCompatimport kotlinx.coroutines.flow.MutableStateFlowimport kotlinx.coroutines.flow.StateFlowimport kotlinx.coroutines.flow.asStateFlow/** * NOUS — Permission orchestrator. * * Centralizes all permission logic so features don't reimplement it. * * Design principles: *   - Just-in-time: ask when feature invoked, not on first launch *   - Progressive: surface only the permission the user actually needs now *   - Auditable: every grant/deny is logged to audit log *   - Graceful: deny → show explanation + Settings deep link, never crash *   - Compose-aware: permission state as Flow + Composable helpers * * For special permissions (Accessibility, NotificationListener, SYSTEM_ALERT_WINDOW, * PACKAGE_USAGE_STATS, BIND_DEVICE_ADMIN), use [SpecialPermission] enum and * request via Settings intent (cannot be granted via runtime dialog). */class PermissionOrchestrator(private val context: Context) {    /** Check if a runtime permission is granted. */    fun isGranted(permission: String): Boolean =        ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED    /** Check if a runtime permission was previously denied with "don't ask again". */    fun isPermanentlyDenied(permission: String): Boolean {        // Cannot directly query this — caller must attempt request and check result        // against rationale. This is a heuristic.        return false    }    /**     * Snapshot of all known permissions and their current grant state.     * Used by Settings → Privacy → Permissions dashboard.     */    fun snapshot(): Map<String, Boolean> = NOUS_PERMISSIONS.associateWith { isGranted(it) }}/** * All permissions NOUS may ever request. Used by Settings dashboard. * * Grouped by feature for the UI. */val NOUS_PERMISSIONS: List<String> = listOf(    // Voice / Audio    "android.permission.RECORD_AUDIO",    "android.permission.MODIFY_AUDIO_SETTINGS",    // Camera / Vision    "android.permission.CAMERA",    // Location    "android.permission.ACCESS_FINE_LOCATION",    "android.permission.ACCESS_COARSE_LOCATION",    "android.permission.ACCESS_BACKGROUND_LOCATION",    // Contacts / Phone / SMS    "android.permission.READ_CONTACTS",    "android.permission.WRITE_CONTACTS",    "android.permission.CALL_PHONE",    "android.permission.READ_PHONE_STATE",    "android.permission.SEND_SMS",    "android.permission.RECEIVE_SMS",    "android.permission.READ_SMS",    // Storage    "android.permission.READ_MEDIA_IMAGES",    "android.permission.READ_MEDIA_VIDEO",    "android.permission.READ_MEDIA_AUDIO",    // Calendar    "android.permission.READ_CALENDAR",    "android.permission.WRITE_CALENDAR",    // Body Sensors    "android.permission.BODY_SENSORS",    "android.permission.ACTIVITY_RECOGNITION",    // Notifications (Android 13+)    "android.permission.POST_NOTIFICATIONS",    // Bluetooth (Android 12+)    "android.permission.BLUETOOTH_SCAN",    "android.permission.BLUETOOTH_CONNECT",)/** * Compose helper: remember the grant state of [permission]. * * Re-checks on lifecycle resume so it stays in sync with user changes from * Settings → App → Permissions. */@Composablefun rememberPermissionState(permission: String): PermissionState {    val context = androidx.compose.ui.platform.LocalContext.current    var granted by remember(permission) {        mutableStateOf(            ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED,        )    }    val launcher = rememberLauncherForActivityResult(        ActivityResultContracts.RequestPermission(),    ) { isGranted ->        granted = isGranted    }    return remember(permission) {        PermissionState(            permission = permission,            isGranted = { granted },            request = { launcher.launch(permission) },        )    }.also { state ->        LaunchedEffect(permission) {            // Re-check on every recomposition from lifecycle events            val now = ContextCompat.checkSelfPermission(context, permission) == PackageManager.PERMISSION_GRANTED            if (now != granted) granted = now        }    }}/** Snapshot of a permission's grant state, with a request callback. */@Stableclass PermissionState(    val permission: String,    private val isGranted: () -> Boolean,    val request: () -> Unit,) {    val granted: Boolean get() = isGranted()}/** * Special permissions that cannot be granted via runtime dialog — must be * granted via Settings. Each maps to a Settings intent action. */enum class SpecialPermission(val settingsAction: String, val description: String) {    ACCESSIBILITY("android.settings.ACCESSIBILITY_SETTINGS", "Accessibility service"),    NOTIFICATION_LISTENER("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS", "Notification listener"),    SYSTEM_ALERT_WINDOW("android.settings.ACTION_MANAGE_OVERLAY_PERMISSION", "Draw over other apps"),    PACKAGE_USAGE_STATS("android.settings.ACTION_USAGE_ACCESS_SETTINGS", "Usage access"),    BIND_DEVICE_ADMIN("android.app.action.ADD_DEVICE_ADMIN", "Device admin"),    MANAGE_EXTERNAL_STORAGE("android.settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION", "All files access"),    BACKGROUND_SENSORS("android.settings.ACTION_REQUEST_BACKGROUND_SENSORS_PERMISSION", "Background body sensors"),}